const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry Definition
    const washington = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017')
      .filter(ee.Filter.eq('name', 'Washington'))
      .geometry();

    // 2. Data Acquisition Parameters
    const collection_id = 'NASA/SMAP/SPL3SMP_E/V005';
    const band_name = 'sm_surface'; // Surface soil moisture

    // Dates
    const date1_start = '2021-11-15';
    const date1_end = '2021-11-16'; // Capture the daily product
    const date2_start = '2021-11-22';
    const date2_end = '2021-11-23'; // Capture the daily product

    // Scale for reduction (SMAP resolution is 9km, so 9000m or 10000m is appropriate)
    const scale = 10000;

    // Function to get and process SMAP data for a given date range
    const getSmapData = (startDate, endDate) => {
      let collection = ee.ImageCollection(collection_id)
        .filterDate(startDate, endDate)
        .filterBounds(washington)
        .select([band_name, 'soil_moisture_quality_flag', 'soil_moisture_retrieval_status']);

      const size = collection.size().getInfo();
      if (size === 0) {
        return { image: null, count: 0, msg: `No images found for ${startDate}.` };
      }

      // Get the first image (should be one per day)
      const image = collection.first();

      // Masking based on quality flags
      const qualityFlag = image.select('soil_moisture_quality_flag').eq(0); // 0 = good quality
      const retrievalStatus = image.select('soil_moisture_retrieval_status').eq(0); // 0 = successful retrieval

      const maskedImage = image.updateMask(qualityFlag.and(retrievalStatus)).select(band_name);

      return { image: maskedImage, count: size, msg: null };
    };

    // --- Process Date 1 (Nov 15, 2021) ---
    const data1 = getSmapData(date1_start, date1_end);
    if (data1.image === null) {
      console.log(data1.msg);
      console.log('C1');
      return;
    }

    const img1 = data1.image;
    const pixelCount1 = img1.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: washington,
      scale: scale,
      maxPixels: 1e9
    }).get(band_name).getInfo();

    if (pixelCount1 === 0 || pixelCount1 === null) {
      console.log(`2021-11-15 Images: ${data1.count}`);
      console.log('No valid pixels for 2021-11-15 after masking.');
      console.log('C2');
      return;
    }

    const mean1 = img1.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: washington,
      scale: scale,
      maxPixels: 1e9
    }).get(band_name).getInfo();

    // --- Process Date 2 (Nov 22, 2021) ---
    const data2 = getSmapData(date2_start, date2_end);
    if (data2.image === null) {
      console.log(data2.msg);
      console.log('C1');
      return;
    }

    const img2 = data2.image;
    const pixelCount2 = img2.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: washington,
      scale: scale,
      maxPixels: 1e9
    }).get(band_name).getInfo();

    if (pixelCount2 === 0 || pixelCount2 === null) {
      console.log(`2021-11-22 Images: ${data2.count}`);
      console.log('No valid pixels for 2021-11-22 after masking.');
      console.log('C2');
      return;
    }

    const mean2 = img2.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: washington,
      scale: scale,
      maxPixels: 1e9
    }).get(band_name).getInfo();

    // 4. Validation & Final Answer
    if (mean1 === null || mean1 === undefined || isNaN(mean1) ||
        mean2 === null || mean2 === undefined || isNaN(mean2)) {
      console.log(`Mean for 2021-11-15: ${mean1}, Mean for 2021-11-22: ${mean2}`);
      console.log('C3');
      return;
    }

    console.log(`2021-11-15 Images: ${data1.count} (Valid Pixels: ${pixelCount1}, Mean Soil Moisture: ${mean1.toFixed(3)})`);
    console.log(`2021-11-22 Images: ${data2.count} (Valid Pixels: ${pixelCount2}, Mean Soil Moisture: ${mean2.toFixed(3)})`);

    if (mean2 > mean1) {
      console.log('A'); // Yes, more moist on Nov 22, 2021
    } else {
      console.log('B'); // No, not more moist on Nov 22, 2021
    }

  } catch (e) {
    console.log(`D: An error occurred: ${e.message}`);
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
